uint16_t dsky_fraction_pair_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;enum dsky_decimal_general_route route=(enum dsky_decimal_general_route)2;uint16_t f,p,end,failures=0;if(n>=128u)return 1;dsky_fraction_pair_input(s,&io,dsky_fraction_pair_numbers[n],&mission);*before=*s;old=io;if(dsky_fraction_pair(s,&io,mission,&route)!=P66_BIAS_OK)++failures;p=dsky_fraction_pair_after_offsets[n];end=dsky_fraction_pair_after_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:2;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:(uint16_t)route;if(p<end&&dsky_fraction_pair_after_patch[p][0]==f)expected=dsky_fraction_pair_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
